"function dcFlag(cc){
    if(!cc||cc.length!==2) return '🌐';
    var a=cc.toUpperCase().charCodeAt(0)-65+0x1F1E6;
    var b=cc.toUpperCase().charCodeAt(1)-65+0x1F1E6;
    return String.fromCodePoint(a)+String.fromCodePoint(b);
  }"
